<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Form 1065 - U.S. Return of Partnership Income (2025)</title>
<script src="https://polyfill.io/v3/polyfill.min.js?features=es6"></script>
<script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
<style>
  * { box-sizing: border-box; }
  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 12px;
    color: #000;
    margin: 0;
    padding: 20px;
    background: #f2f2f2;
  }
  .page {
    max-width: 1150px;
    margin: 0 auto;
    background: #fff;
    border: 2px solid #000;
  }
  .top-header {
    display: flex;
    border-bottom: 2px solid #000;
  }
  .form-num-box {
    width: 150px;
    border-right: 1px solid #000;
    padding: 6px;
  }
  .form-num-box .form-label { font-size: 11px; }
  .form-num-box .num { font-size: 40px; font-weight: bold; line-height: 1; }
  .treasury {
    font-size: 10px;
    margin-top: 10px;
  }
  .title-box {
    flex: 1;
    border-right: 1px solid #000;
    padding: 6px 10px;
    text-align: center;
  }
  .title-box h1 {
    font-size: 26px;
    margin: 4px 0 10px 0;
  }
  .title-box .cal-year {
    font-size: 12.5px;
    margin-bottom: 6px;
  }
  .dashed-line {
    display: inline-block;
    border-bottom: 1px dashed #000;
    min-width: 140px;
    height: 12px;
  }
  .title-box .goto {
    font-size: 12.5px;
  }
  .omb-box {
    width: 190px;
    padding: 6px 8px;
    text-align: right;
  }
  .omb-box .omb-text { font-size: 11px; text-align: right; }
  .omb-box .year {
    text-align: right;
    margin-top: 30px;
    font-size: 34px;
  }
  .year .light { color: #999; font-weight: bold; }
  .year .bold { font-weight: bold; }

  /* A-F grid */
  .abcdef {
    display: grid;
    grid-template-columns: 190px 1fr 130px 190px;
    border-bottom: 2px solid #000;
  }
  .cell {
    border-right: 1px solid #000;
    border-bottom: 1px solid #000;
    padding: 4px 6px;
    min-height: 34px;
  }
  .cell:last-child { border-right: none; }
  .label-letter { font-weight: bold; }
  .abcdef .row3 { grid-column: 1 / span 4; display: grid; grid-template-columns: 190px 1fr 130px 190px; }
  .row-line {
    display: grid;
    grid-template-columns: 190px 1fr 130px 190px;
  }
  .row-line .cell:last-child { border-bottom: 1px solid #000; }
  .abcdef .row-line:last-child .cell { border-bottom: none; }

  .de-stack {
    display: flex;
    flex-direction: column;
    border-left: 1px solid #000;
    margin-left: -1px;
  }
  .de-stack .cell { border-right: none; flex: 1; }

  /* G through K */
  .ghijk {
    padding: 4px 8px;
    border-bottom: 2px solid #000;
  }
  .ghijk .line { display: flex; align-items: center; margin: 4px 0; flex-wrap: wrap; }
  .letter-bold { font-weight: bold; width: 18px; display: inline-block; }
  .chk {
    display: inline-block;
    width: 11px; height: 11px;
    border: 1px solid #000;
    margin: 0 4px 0 10px;
    vertical-align: middle;
  }
  .num-paren { font-weight: bold; margin-left: 6px;}
  .fill-dash {
    flex: 1;
    border-bottom: 1px dashed #000;
    margin: 0 6px;
    height: 12px;
  }
  .j-line { display: flex; justify-content: space-between; align-items: center; }
  .dots { flex: 1; border-bottom: 1px dotted #000; height: 10px; margin: 0 6px;}

  .caution {
    padding: 5px 8px;
    border-bottom: 2px solid #000;
    font-size: 12px;
  }

  /* main body layout */
  .body-flex {
    display: flex;
  }
  .side-label {
    width: 22px;
    border-right: 2px solid #000;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .side-label span {
    writing-mode: vertical-rl;
    transform: rotate(180deg);
    font-weight: bold;
    font-size: 15px;
    letter-spacing: 1px;
  }
  .side-label.deductions span { font-size: 13px; }
  .side-note {
    font-size: 8.5px;
    writing-mode: vertical-rl;
    transform: rotate(180deg);
    margin-left: 2px;
    font-weight: normal;
  }
  .lines {
    flex: 1;
  }
  .line-row {
    display: grid;
    grid-template-columns: 45px 1fr 45px 210px;
    border-bottom: 1px solid #000;
    align-items: stretch;
  }
  .line-row.no-num-border { }
  .ln-num {
    padding: 4px 4px;
    font-weight: bold;
    border-right: 1px solid #000;
    display: flex;
    align-items: center;
  }
  .ln-desc {
    padding: 4px 8px;
    border-right: 1px solid #000;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
  }
  .ln-num2 {
    padding: 4px 4px;
    font-weight: bold;
    border-right: 1px solid #000;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .ln-amt {
    padding: 4px 6px;
  }
  .ln-amt.shaded { background: #ccc; }
  .sub-inline {
    display: flex;
    align-items: center;
    flex: 1;
    flex-wrap: wrap;
  }
  .inline-dots {
    border-bottom: 1px dotted #000;
    flex: 1;
    height: 10px;
    margin: 0 6px;
    min-width: 40px;
  }
  .inline-blank {
    border-bottom: 1px solid #000;
    display: inline-block;
    width: 140px;
    height: 12px;
    margin: 0 6px;
  }
  .bold-line { font-weight: bold; }

  /* 16a/16b special sub rows */
  .sub16 {
    display: grid;
    grid-template-columns: 1fr 45px 130px;
    align-items: center;
    width: 100%;
  }
  .sub16 .lbl16 { font-weight: bold; text-align: center; border-left: 1px solid #000; padding: 2px 0;}
  .sub16 .val16 { border-left: 1px solid #000; padding: 2px 6px; }

  /* Sign here / preparer */
  .sign-section {
    display: grid;
    grid-template-columns: 130px 1fr 300px;
    border-top: 2px solid #000;
  }
  .sign-label {
    font-weight: bold;
    font-size: 20px;
    padding: 8px;
    border-right: 1px solid #000;
    display: flex;
    align-items: flex-start;
  }
  .sign-decl {
    border-right: 1px solid #000;
    padding: 6px 10px;
    font-size: 11px;
  }
  .sig-line-row {
    display: flex;
    margin-top: 28px;
    font-size: 10.5px;
  }
  .sig-line-row .part {
    flex: 1;
    border-top: 1px solid #000;
    padding-top: 2px;
    margin-right: 20px;
  }
  .sig-line-row .part.date {
    flex: 0 0 200px;
  }
  .irs-discuss {
    padding: 6px 10px;
    font-size: 11px;
  }
  .irs-box {
    border: 2px solid #000;
    padding: 6px;
    height: 100%;
  }
  .yn { margin-top: 6px; }
  .yn .chk { margin-left: 12px; margin-right: 3px; }

  .preparer-section {
    display: grid;
    grid-template-columns: 130px 1fr;
    border-top: 1px solid #000;
  }
  .preparer-label {
    font-weight: bold;
    font-size: 15px;
    padding: 8px;
    border-right: 1px solid #000;
  }
  .prep-rows { display: flex; flex-direction: column; }
  .prep-row {
    display: grid;
    grid-template-columns: 1fr 1fr 130px 90px 90px;
    border-bottom: 1px solid #000;
  }
  .prep-row:last-child { border-bottom: none; }
  .prep-cell {
    border-right: 1px solid #000;
    padding: 4px 6px;
    min-height: 32px;
  }
  .prep-cell:last-child { border-right: none; }
  .prep-row2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    border-bottom: 1px solid #000;
  }
  .prep-row3 {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .footer {
    display: flex;
    justify-content: space-between;
    padding: 6px 10px;
    border-top: 2px solid #000;
    font-size: 11.5px;
    align-items: center;
  }
</style>
</head>
<body>
<div class="page">

  <!-- Top Header -->
  <div class="top-header">
    <div class="form-num-box">
      <div class="form-label"><b>Form</b></div>
      <div class="num">1065</div>
      <div class="treasury">Department of the Treasury<br>Internal Revenue Service</div>
    </div>
    <div class="title-box">
      <h1>U.S. Return of Partnership Income</h1>
      <div class="cal-year">
        <b>For calendar year 2025, or tax year beginning</b> <span class="dashed-line"></span> , 2025, ending <span class="dashed-line"></span> , 20 <span class="dashed-line" style="min-width:30px;"></span> .
      </div>
      <div class="goto"><b>Go to <i>www.irs.gov/Form1065</i> for instructions and the latest information.</b></div>
    </div>
    <div class="omb-box">
      <div class="omb-text">OMB No. 1545-0123</div>
      <div class="year"><span class="light">20</span><span class="bold">25</span></div>
    </div>
  </div>

  <!-- A - F Grid -->
  <div class="abcdef">
    <div class="row-line">
      <div class="cell"><span class="label-letter">A</span> Principal business activity</div>
      <div class="cell"><b>Name of partnership</b></div>
      <div class="cell" style="grid-column: 3 / span 2; border-right:none; position:relative;">
        <div style="position:absolute; right:8px; top:4px; width:190px; border-left:1px solid #000; padding-left:8px;">
          <span class="label-letter">D</span> <b>Employer<br>identification number</b>
        </div>
      </div>
    </div>
    <div class="row-line">
      <div class="cell"><span class="label-letter">B</span> Principal product or service</div>
      <div class="cell" style="display:grid; grid-template-columns: 1fr 150px;">
        <div style="border-right:1px solid #000; padding-right:6px;"><b>Number and street</b></div>
        <div style="padding-left:6px;"><b>Room or suite no.</b></div>
      </div>
      <div class="cell" style="grid-column: 3 / span 2; border-right:none; position:relative;">
        <div style="position:absolute; right:8px; top:4px; width:190px; border-left:1px solid #000; padding-left:8px;">
          <span class="label-letter">E</span> Date business started
        </div>
      </div>
    </div>
    <div class="row-line" style="grid-template-columns: 190px 1fr 1fr 1fr 190px;">
      <div class="cell"><span class="label-letter">C</span> Business code number</div>
      <div class="cell"><b>City or town</b></div>
      <div class="cell"><b>State or province</b></div>
      <div class="cell" style="display:grid; grid-template-columns: 1fr 1fr;">
        <div style="border-right:1px solid #000; padding-right:6px;"><b>Country</b></div>
        <div style="padding-left:6px;"><b>ZIP or foreign<br>postal code</b></div>
      </div>
      <div class="cell" style="border-right:none;">
        <span class="label-letter">F</span> Total assets <span style="font-size:10px;">(see instructions)</span>
        <div style="margin-top:14px;">$</div>
      </div>
    </div>
  </div>

  <!-- G - K -->
  <div class="ghijk">
    <div class="line">
      <span class="letter-bold">G</span> Check applicable boxes:
      <span class="num-paren">(1)</span><span class="chk"></span> Initial return
      <span class="num-paren">(2)</span><span class="chk"></span> Final return
      <span class="num-paren">(3)</span><span class="chk"></span> Name change
      <span class="num-paren">(4)</span><span class="chk"></span> Address change
      <span class="num-paren">(5)</span><span class="chk"></span> Amended return
    </div>
    <div class="line">
      <span class="letter-bold">H</span> Check accounting method:
      <span class="num-paren">(1)</span><span class="chk"></span> Cash
      <span class="num-paren">(2)</span><span class="chk"></span> Accrual
      <span class="num-paren">(3)</span><span class="chk"></span> Other (specify): <span class="fill-dash"></span>
    </div>
    <div class="line">
      <span class="letter-bold">I</span> Number of Schedules K-1. Attach one for each person who was a partner at any time during the tax year: <span class="fill-dash" style="max-width:280px;"></span>
    </div>
    <div class="j-line">
      <span><span class="letter-bold">J</span> Check if Schedules C and M-3 are attached</span>
      <span class="dots"></span>
      <span class="chk"></span>
    </div>
    <div class="line">
      <span class="letter-bold">K</span> Check if partnership:
      <span class="num-paren">(1)</span><span class="chk"></span> Aggregated activities for section 465 at-risk purposes
      <span class="num-paren">(2)</span><span class="chk"></span> Grouped activities for section 469 passive activity purposes
    </div>
  </div>

  <div class="caution">
    <b>Caution:</b> Include <b>only</b> trade or business income and expenses on lines 1a through 23 below. See instructions for more information.
  </div>

  <!-- INCOME SECTION -->
  <div class="body-flex">
    <div class="side-label"><span>Income</span></div>
    <div class="lines">
      <div class="line-row">
        <div class="ln-num">1a</div>
        <div class="ln-desc">
          <div class="sub-inline">Gross receipts or sales <span class="inline-blank"></span> <b>b</b>&nbsp;Less returns and allowances <span class="inline-blank"></span> <b>c</b>&nbsp;Balance</div>
        </div>
        <div class="ln-num2">1c</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">2</div>
        <div class="ln-desc"><div class="sub-inline">Cost of goods sold (attach Form 1125-A) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">2</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">3</div>
        <div class="ln-desc"><div class="sub-inline">Gross profit. Subtract line 2 from line 1c <span class="inline-dots"></span></div></div>
        <div class="ln-num2">3</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">4</div>
        <div class="ln-desc"><div class="sub-inline">Ordinary income (loss) from other partnerships, estates, and trusts (attach statement) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">4</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">5</div>
        <div class="ln-desc"><div class="sub-inline">Net farm profit (loss) (attach Schedule F (Form 1040)) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">5</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">6</div>
        <div class="ln-desc"><div class="sub-inline">Net gain (loss) from Form 4797, Part II, line 17 (attach Form 4797) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">6</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">7</div>
        <div class="ln-desc"><div class="sub-inline">Other income (loss) (attach statement) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">7</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">8</div>
        <div class="ln-desc"><div class="sub-inline bold-line"><b>Total income (loss).</b>&nbsp;Combine lines 3 through 7 <span class="inline-dots"></span></div></div>
        <div class="ln-num2">8</div>
        <div class="ln-amt"></div>
      </div>
    </div>
  </div>

  <!-- DEDUCTIONS SECTION -->
  <div class="body-flex">
    <div class="side-label deductions">
      <span>Deductions <span class="side-note">(see instructions for limitations)</span></span>
    </div>
    <div class="lines">
      <div class="line-row">
        <div class="ln-num">9</div>
        <div class="ln-desc"><div class="sub-inline">Salaries and wages (other than to partners) (less employment credits) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">9</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">10</div>
        <div class="ln-desc"><div class="sub-inline">Guaranteed payments to partners <span class="inline-dots"></span></div></div>
        <div class="ln-num2">10</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">11</div>
        <div class="ln-desc"><div class="sub-inline">Repairs and maintenance <span class="inline-dots"></span></div></div>
        <div class="ln-num2">11</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">12</div>
        <div class="ln-desc"><div class="sub-inline">Bad debts <span class="inline-dots"></span></div></div>
        <div class="ln-num2">12</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">13</div>
        <div class="ln-desc"><div class="sub-inline">Rent <span class="inline-dots"></span></div></div>
        <div class="ln-num2">13</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">14</div>
        <div class="ln-desc"><div class="sub-inline">Taxes and licenses <span class="inline-dots"></span></div></div>
        <div class="ln-num2">14</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">15</div>
        <div class="ln-desc"><div class="sub-inline">Interest (see instructions) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">15</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">16a</div>
        <div class="ln-desc">
          <div class="sub16">
            <div style="border-left:none;">Depreciation (if required, attach Form 4562) <span class="inline-dots"></span></div>
            <div class="lbl16">16a</div>
            <div class="val16"></div>
          </div>
        </div>
        <div class="ln-num2" style="visibility:hidden;">x</div>
        <div class="ln-amt shaded"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">b</div>
        <div class="ln-desc">
          <div class="sub16">
            <div style="border-left:none;">Less depreciation reported on Form 1125-A and elsewhere on return <span class="inline-dots"></span></div>
            <div class="lbl16">16b</div>
            <div class="val16"></div>
          </div>
        </div>
        <div class="ln-num2">16c</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">17</div>
        <div class="ln-desc"><div class="sub-inline">Depletion <b>(Do not deduct oil and gas depletion.)</b> <span class="inline-dots"></span></div></div>
        <div class="ln-num2">17</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">18</div>
        <div class="ln-desc"><div class="sub-inline">Retirement plans, etc. <span class="inline-dots"></span></div></div>
        <div class="ln-num2">18</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">19</div>
        <div class="ln-desc"><div class="sub-inline">Employee benefit programs <span class="inline-dots"></span></div></div>
        <div class="ln-num2">19</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">20</div>
        <div class="ln-desc"><div class="sub-inline">Energy efficient commercial buildings deduction (attach Form 7205) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">20</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">21</div>
        <div class="ln-desc"><div class="sub-inline">Other deductions (attach statement) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">21</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">22</div>
        <div class="ln-desc"><div class="sub-inline"><b>Total deductions.</b>&nbsp;Add the amounts shown in the far right column for lines 9 through 21 <span class="inline-dots"></span></div></div>
        <div class="ln-num2">22</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row" style="border-bottom: 2px solid #000;">
        <div class="ln-num" style="border-right:none;">23</div>
        <div class="ln-desc" style="border-right:1px solid #000; grid-column:1/1;"></div>
        <div class="ln-desc"><div class="sub-inline"><b>Ordinary business income (loss).</b>&nbsp;Subtract line 22 from line 8 <span class="inline-dots"></span></div></div>
        <div class="ln-num2">23</div>
        <div class="ln-amt"></div>
      </div>
    </div>
  </div>

  <!-- TAX AND PAYMENT SECTION -->
  <div class="body-flex">
    <div class="side-label"><span>Tax and Payment</span></div>
    <div class="lines">
      <div class="line-row">
        <div class="ln-num">24</div>
        <div class="ln-desc"><div class="sub-inline">Interest due under the look-back method—completed long-term contracts (attach Form 8697) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">24</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">25</div>
        <div class="ln-desc"><div class="sub-inline">Interest due under the look-back method—income forecast method (attach Form 8866) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">25</div>
        <div class="ln-amt"></div>
      </div>
      <div class="line-row">
        <div class="ln-num">26</div>
        <div class="ln-desc"><div class="sub-inline">BBA AAR imputed underpayment (see instructions) <span class="inline-dots"></span></div></div>
        <div class="ln-num2">26</div>
        <div class="ln-amt"></div>
      </div>
